using Xunit;

public class U07_AlarmsTest
{
    [Fact]
    public void MediumAlarmColorAndFrequencyTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.Medium);

        // Act
        alarm.Activate();

        // Assert
        Assert.Equal(Color.Yellow, alarm.Color);
        Assert.Equal(0.5Hz, alarm.Frequency);
    }

    [Fact]
    public void HighAlarmAudioTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.High);

        // Act
        alarm.Activate();

        // Assert
        Assert.Equal(10, alarm.PulseCount);
        Assert.Equal(200ms, alarm.PulseDuration);
        Assert.Equal(500Hz, alarm.PulseFrequency);
    }

    [Fact]
    public void HighAlarmAudioTest2()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.High);

        // Act
        alarm.Activate();

        // Assert
        Assert.Equal(4, alarm.PulseCount);
        Assert.Equal(200ms, alarm.PulseDuration);
        Assert.Equal(500Hz, alarm.PulseFrequency);
    }

    [Fact]
    public void AudioPauseTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.Medium);

        // Act
        alarm.PauseAudio();

        // Assert
        Assert.True(alarm.IsAudioPaused);
        Assert.Equal(60, alarm.AudioPauseDuration);
    }

    [Fact]
    public void ApneaAlarmTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.Medium);

        // Act
        alarm.TriggerApneaAlarm();

        // Assert
        Assert.Equal("APNEA ALARM", alarm.DisplayText);
    }

    [Fact]
    public void BreathRateAlarmTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.Medium);

        // Act
        alarm.TriggerBreathRateAlarm();

        // Assert
        Assert.Equal("HIGH BREATH RATE", alarm.DisplayText);
    }

    [Fact]
    public void MaxBreathRateSettingTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.Medium);

        // Assert
        Assert.True(alarm.HasMaxBreathRateSetting);
    }

    [Fact]
    public void LowPressureAlarmTest()
    {
        // Arrange
        var alarm = new Alarm(AlarmSeverity.High);

        // Act
        alarm.TriggerLowPressureAlarm();

        // Assert
        Assert.Equal("LOW INSP P", alarm.DisplayText);
    }
}

